        try c.sendTo(receiver, amount) { reverted = false; } catch { reverted = true; }
        uint cAfter = address(c).balance;
        uint rAfter = receiver.balance;
        assert(
            reverted
                ? (cAfter == cBefore && rAfter == rBefore)
                : (cBefore == cAfter + amount && rAfter == rBefore + amount)
        );
    }
    receive() external payable {}
}

